content.css:
:host {
  --atlyn-primary: #2563eb;
  --atlyn-text: #172033;
  --atlyn-muted: #526179;
  --atlyn-warning: #9a6700;
  --atlyn-surface: #ffffff;
  --atlyn-border: #d5dce7;
}
.atlyn-funnel {
  box-sizing: border-box;
  color: var(--atlyn-text);
  background: var(--atlyn-surface);
  font-family: "Segoe UI", Arial, sans-serif;
  font-size: 13px;
  height: 100%;
  min-height: 80px;
  min-width: 160px;
  overflow: auto;
  padding: 10px;
  overscroll-behavior: contain;
  touch-action: pan-y;
}
.atlyn-funnel[data-high-contrast="true"] {
  --atlyn-primary: CanvasText;
  --atlyn-text: CanvasText;
  --atlyn-muted: CanvasText;
  --atlyn-warning: CanvasText;
  --atlyn-surface: Canvas;
  --atlyn-border: CanvasText;
}
.atlyn-funnel[data-high-contrast="true"] .atlyn-bar,
.atlyn-funnel[data-high-contrast="true"] .atlyn-dimmed {
  opacity: 1;
}
.atlyn-summary {
  align-items: baseline;
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: space-between;
}
.atlyn-summary h2 {
  font-size: 16px;
  margin: 0;
}
.atlyn-summary-metric {
  font-weight: 700;
}
.atlyn-summary-intake {
  color: var(--atlyn-muted);
}
.atlyn-warnings {
  border-inline-start: 3px solid var(--atlyn-warning);
  color: var(--atlyn-warning);
  margin: 8px 0;
  padding-inline-start: 8px;
}
.atlyn-warnings ul {
  margin: 2px 0;
  padding-inline-start: 18px;
}
.atlyn-chart {
  display: block;
  height: auto;
  max-width: 100%;
  min-height: 220px;
  overflow: visible;
  width: 100%;
}
.atlyn-chart-scroll {
  max-width: 100%;
  overflow: auto;
  overscroll-behavior: contain;
  touch-action: pan-y;
  -webkit-overflow-scrolling: touch;
}
.atlyn-bar {
  fill: var(--atlyn-primary);
  opacity: 0.9;
  stroke: var(--atlyn-text);
  stroke-width: 1;
}
.atlyn-bar.atlyn-blank {
  fill: none;
  stroke-dasharray: 4 3;
}
.atlyn-bar.atlyn-negative {
  fill: none;
  stroke-dasharray: 3 2;
  stroke-width: 2;
}
.atlyn-bar.atlyn-invalid {
  fill: none;
  stroke-dasharray: 1 3;
  stroke-width: 2;
}
.atlyn-state-marker {
  fill: none;
  stroke: var(--atlyn-text);
  stroke-width: 2;
}
.atlyn-state-marker.atlyn-blank {
  stroke-dasharray: 4 3;
}
.atlyn-state-marker.atlyn-negative {
  stroke-dasharray: 3 2;
}
.atlyn-dimmed {
  opacity: 0.35;
}
.atlyn-chart-label {
  fill: var(--atlyn-text);
  font-size: 11px;
  white-space: nowrap;
}
.atlyn-stage-list {
  display: grid;
  gap: 4px;
}
.atlyn-stage-item {
  min-width: 0;
}
.atlyn-stage-button {
  background: transparent;
  border: 1px solid var(--atlyn-border);
  border-radius: 4px;
  color: var(--atlyn-text);
  cursor: pointer;
  font: inherit;
  line-height: 1.3;
  min-height: 36px;
  padding: 7px 9px;
  text-align: start;
  touch-action: manipulation;
  width: 100%;
}
.atlyn-stage-button:hover,
.atlyn-stage-button:focus-visible {
  background: var(--atlyn-surface);
  outline: 2px solid var(--atlyn-primary);
  outline-offset: 1px;
}
.atlyn-accessible-table {
  border-collapse: collapse;
  clip: rect(0 0 0 0);
  height: 1px;
  margin: -1px;
  overflow: hidden;
  position: absolute;
  width: 1px;
}
.atlyn-accessible-table td,
.atlyn-accessible-table th {
  border: 1px solid var(--atlyn-border);
  padding: 3px;
}
.atlyn-empty {
  color: var(--atlyn-muted);
  margin: 8px;
}
.atlyn-funnel[data-state="error"] .atlyn-empty {
  color: var(--atlyn-warning);
}
.atlyn-accessible-table:focus-visible {
  clip: auto;
  height: auto;
  margin: 0;
  outline: 2px solid var(--atlyn-primary);
  overflow: auto;
  position: static;
  width: 100%;
}
.atlyn-funnel[data-compact="true"] {
  padding: 6px;
}
.atlyn-funnel[data-compact="true"] .atlyn-chart {
  min-height: 150px;
}
.atlyn-funnel[data-compact="true"] .atlyn-stage-button {
  min-height: 44px;
}
@media (prefers-reduced-motion: no-preference) {
  .atlyn-bar {
    transition: opacity 120ms ease, width 120ms ease;
  }
}
@media (prefers-reduced-motion: reduce) {
  .atlyn-bar {
    transition: none;
  }
}
